#[macro_export]
macro_rules! combine_with_next_internal {
    ($next:expr) => {
        $next
    };
    ($next:expr, $($expr:expr),* $(,)?) => {
        $next $(
            .and($expr)
        )*
    };
}

#[macro_export]
macro_rules! combine_spec_entails_always_n {
    [$($tail:tt)*] => {
