}
#[macro_export]
macro_rules! combine_spec_entails_always_n_internal {
    ($spec:expr, $partial_spec:expr, $($tail:tt)*) => {
        assert_by(
            valid($spec.implies(always(combine_with_next!($($tail)*)))),
            {
                entails_always_and_n!($spec, $($tail)*);
            }
        );
